package io.xeros.solo;
import io.xeros.*;import io.xeros.content.minigames.toa.*;import io.xeros.content.combat.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.util.*;import java.lang.reflect.*;import java.util.function.IntUnaryOperator;
public final class ToaSoloPlayableCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(){Player p=BossRoutesCheck.actor();p.setLoginName("toa65qa");p.setDisplayName("Toa65qa");p.getHealth().setMaximumHealth(5000);p.getHealth().reset();return p;}static void apply(Player p){BossesPlayableCheck.applied(p);p.teleTimer=0;}static NPC boss(Player p){return p.getInstance().getNpcs().stream().filter(n->!n.isDead()&&!n.isUnregister()).findFirst().orElseThrow();}static void clear(Player p){if(p.getInstance()!=null)p.getInstance().remove(p);for(NPC n:new ArrayList<>(Arrays.asList(NPCHandler.npcs)))if(n!=null&&n.isUnregister())n.processDeregistration();BossesPlayableCheck.clear(p);}
 static int kill(Player p,NPC n){int phases=0;while(!n.isDead()&&phases<5){n.appendDamage(p,n.getHealth().getCurrentHealth(),Hitmark.HIT);phases++;}ok(n.isDead(),"Phase cannot finish");for(int i=0;i<40&&!n.needRespawn&&!n.isUnregister();i++)Server.npcHandler.getNpcProcess().process(n.getIndex());return phases;}
 static void force(Player p,int item)throws Exception{int index=-1;for(int i=0;i<SoloToa.UNIQUES.length;i++)if(SoloToa.UNIQUES[i]==item){index=i;break;}ok(index>=0,"Rare fixture");final int k=index;Field f=SoloToa.class.getDeclaredField("lootRoll");f.setAccessible(true);f.set(p.getInstance(),(IntUnaryOperator)(b->b==10?0:k));}
 static void complete()throws Exception{Player p=actor();ok(SoloToa.enter(p),"Solo ToA entry");apply(p);force(p,27275);int forms=0;for(int i=0;i<5;i++){NPC n=boss(p);ok(PathFinder.getPathFinder().accessable(p,p.absX+1,p.absY)||PathFinder.getPathFinder().accessable(p,p.absX-1,p.absY)||PathFinder.getPathFinder().accessable(p,p.absX,p.absY+1)||PathFinder.getPathFinder().accessable(p,p.absX,p.absY-1),"ToA arrival tile trapped "+i);ok(n.getNpcId()==SoloToa.IDS[i]&&n.getName().equals(SoloToa.NAMES[i]),"Wrong ToA boss/model "+i);Player outsider=actor();ok(!n.canBeDamaged(outsider),"Outside player can damage");PlayerHandler.players[1]=p;SkillsAuditCheck.clear(outsider);forms+=kill(p,n);if(i<4){ok(p.toaSoloStage==i+1,"ToA checkpoint");SkillsAuditCheck.tick(5);apply(p);}}ok(forms==8&&p.getInstance()==null&&p.toaCompletions==1&&p.toaSoloStage==0&&p.getItems().getInventoryCount(27275)==1,"ToA completion/phases/reward");ok(PlayerSave.saveGameInstant(p),"ToA save");Player q=actor();ok(PlayerSave.loadGame(q,"toa65qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.toaCompletions==1&&q.toaSoloStage==0&&q.getItems().getInventoryCount(27275)==1&&q.getTeleportToX()==3359,"ToA reward reload");clear(p);clear(q);System.out.println("TOA_SOLO_FIVE_NATIVE_MODELS_EIGHT_FORMS_REAL_NPC_DEATHS_OUTSIDER_GATE_SHADOW_ONE_COMPLETION_CHECKPOINTS_AND_REAL_SAVE_RELOAD_PASS");}
 static void gear()throws Exception{for(int id:new int[]{27226,27229,27232,26219,25975,25985,27275}){Player p=actor();p.toaSoloStage=4;SoloToa.enter(p);apply(p);force(p,id);if(id==27275)while(p.getItems().freeSlots()>0)ok(p.getItems().addItem(526,1),"Full bag");NPC n=boss(p);kill(p,n);n.onDeath();ok(p.toaCompletions==1&&(id==27275?p.getItems().bankContains(id):p.getItems().getInventoryCount(id)==1),"Unique/full bag/duplicate "+id);clear(p);}System.out.println("TOA_SOLO_SEVEN_UNIQUES_MASORI_FANG_LIGHTBEARER_WARD_SHADOW_SINGLE_REWARD_FULL_BAG_BANK_PASS");}
 static void safety()throws Exception{for(int i=0;i<4;i++){Player p=actor();if(i==0)p.isDead=true;if(i==1)p.getHealth().setCurrentHealth(0);if(i==2)p.isBanking=true;if(i==3)p.teleTimer=2;ok(!SoloToa.enter(p),"Entry guard "+i);clear(p);}Player p=actor();SoloToa.enter(p);apply(p);ok(!SoloToa.enter(p),"Duplicate ToA");kill(p,boss(p));ok(PlayerSave.saveGameInstant(p),"Checkpoint save");Player q=actor();ok(PlayerSave.loadGame(q,"toa65qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.toaSoloStage==1&&q.getTeleportToX()==3359,"Checkpoint reload");clear(p);PlayerHandler.players[1]=q;SoloToa.enter(q);apply(q);ok(boss(q).getNpcId()==11730,"Checkpoint resumed wrong boss");NPC n=boss(q);Method m=n.getClass().getDeclaredMethod("special");m.setAccessible(true);for(int i=0;i<4;i++)m.invoke(n);int hp=q.getHealth().getCurrentHealth();q.getInstance().remove(q);SkillsAuditCheck.tick(5);ok(q.getHealth().getCurrentHealth()==hp,"Delayed raid hit after exit");clear(q);System.out.println("TOA_SOLO_DEAD_ZERO_HP_BANK_TELEPORT_DUPLICATE_GUARDS_CHECKPOINT_REENTRY_AND_DELAYED_HIT_EXIT_CANCEL_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;complete();gear();safety();System.out.println("TOA_SOLO_BOSS_CIRCUIT_V65_PASS");System.exit(0);}
}
